SPARQL_Query:
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?numEmployees
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label ;
           sdk:hasNumberOfEmployees ?numEmployees .
  FILTER(CONTAINS(LCASE(STR(?label)), "steel"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasCertificate ?cert .
  ?cert a sdk:ISO9001 .
  OPTIONAL { ?m rdfs:label ?nameEn FILTER(LANGMATCHES(LANG(?nameEn), "en")) }
  OPTIONAL { ?m rdfs:label ?nameNoLang FILTER(LANG(?nameNoLang) = "") }
  BIND(COALESCE(?nameEn, ?nameNoLang) AS ?name)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?naicsText
WHERE {
  ?classifier sdk:hasNAICSCodeValue ?code ;
              sdk:hasNAICSTextValue ?naicsText .
  FILTER (regex(str(?code), "^332996(\\.0)?$"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?code
WHERE {
  ?classifier sdk:hasNAICSTextValue ?text ;
              sdk:hasNAICSCodeValue ?code .
  FILTER(CONTAINS(UCASE(STR(?text)), "PIPE AND PIPE FITTING"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?businessDescription WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?businessDescription .
  FILTER(CONTAINS(LCASE(STR(?name)), "fabrication"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT DISTINCT ?zipCode
WHERE {
  ?site a sdk:GeospatialLocation ;
        sdk:hasPostalAddress ?addr ;
        sdk:hasZIPcode ?zip .
  ?addr iof-scro:hasTextValue ?addrText .
  FILTER(CONTAINS(LCASE(STR(?addrText)), "suite"))
  ?zip sdk:hasIntegerValue ?zipCode .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?latitude
WHERE {
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city ;
        sdk:hasSpatialCoordinates ?coords .
  ?city rdfs:label ?cityLabel .
  ?coords sdk:hasLatitudeValue ?latitude .
  FILTER(CONTAINS(LCASE(STR(?cityLabel)), "springfield"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stateName
WHERE {
  ?city a sdk:City ;
        rdfs:label ?cityName ;
        sdk:locatedInState ?state .
  FILTER(CONTAINS(?cityName, "San "))
  ?state a sdk:State ;
         rdfs:label ?stateName .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?naicsCode
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasPrimaryNAICSClassifier ?naics .
  ?naics sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(CONTAINS(LCASE(STR(?label)), "precision"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?industry ?industryLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
  FILTER(CONTAINS(LCASE(STR(?manufacturerLabel)), "automation"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:manufactures ?product .
  OPTIONAL { ?product rdfs:label ?productLabel }
  FILTER(CONTAINS(LCASE(STR(?companyLabel)), "tooling"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?processCapability ?processCapabilityLabel ?company ?companyLabel
WHERE {
  ?company rdfs:label ?companyLabel ;
           sdk:hasProcessCapability ?processCapability .
  ?processCapability rdfs:label ?processCapabilityLabel .
  FILTER(CONTAINS(LCASE(STR(?companyLabel)), "aerospace"))
}
ORDER BY ?companyLabel ?processCapabilityLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT DISTINCT ?org ?orgLabel ?materialCapability ?materialCapabilityLabel
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?orgLabel ;
       sdk:hasMaterialCapability ?materialCapability .
  OPTIONAL { ?materialCapability rdfs:label ?materialCapabilityLabel . }
  FILTER(CONTAINS(LCASE(STR(?orgLabel)), "metal"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?certificate ?certLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?mfgLabel ;
                sdk:hasCertificate ?certificate .
  OPTIONAL { ?certificate rdfs:label ?certLabel . }
  FILTER(CONTAINS(LCASE(STR(?mfgLabel)), "plastics"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?city ?cityLabel WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?name ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
  FILTER(CONTAINS(LCASE(STR(?name)), "robotics"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?state ?stateLabel
WHERE {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:organizationLocatedIn ?site .
  FILTER(CONTAINS(LCASE(STR(?name)), "valve")) .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?zipVal
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?label ;
       sdk:organizationLocatedIn ?site .
  FILTER(CONTAINS(LCASE(STR(?label)), "casting"))
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue ?zipVal .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?latitude ?longitude
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?latitude ;
          sdk:hasLongitudeValue ?longitude .
  FILTER(CONTAINS(LCASE(STR(?name)), "surface finish"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel (COUNT(DISTINCT ?mfg) AS ?manufacturerCount)
WHERE {
  ?mfg a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel }
}
GROUP BY ?city ?cityLabel
ORDER BY ?cityLabel ?city

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel. }
}
GROUP BY ?industry ?industryLabel
ORDER BY ?industryLabel ?industry

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel (AVG(?emp) AS ?avgEmployees)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?empLit ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?emp)
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?certificate (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?certificate .
}
GROUP BY ?certificate
ORDER BY ?certificate

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naics ?naicsCode ?naicsText (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasPrimaryNAICSClassifier ?naics .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCode . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsText . }
}
GROUP BY ?naics ?naicsCode ?naicsText
ORDER BY ?naicsCode

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (COUNT(DISTINCT ?product) AS ?productCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (COUNT(DISTINCT ?capability) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  {
    ?manufacturer sdk:hasProcessCapability ?capability .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?capability .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT (COUNT(DISTINCT ?m) AS ?count)
WHERE {
  ?m a iof-core:Manufacturer .
  FILTER NOT EXISTS {
    ?m iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

ASK WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?certificate .
  ?certificate a sdk:ISO9001 .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?indRE ;
                sdk:suppliesToIndustry ?indUtil .
  ?indRE a sdk:RenewableEnergyIndustry .
  ?indUtil a sdk:UtilitiesIndustry .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:hasPrimaryNAICSClassifier ?naics .
  FILTER(CONTAINS(LCASE(STR(?name)), "pipe"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product rdfs:label ?productLabel .
  FILTER(CONTAINS(LCASE(STR(?productLabel)), "valve"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER (lcase(str(?cityLabel)) = "phoenix")
  FILTER (lcase(str(?stateLabel)) = "arizona")
  FILTER NOT EXISTS { ?manufacturer sdk:hasCertificate ?cert }
}
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

ASK WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coord .
  ?coord sdk:hasLatitudeValue ?lat ;
         sdk:hasLongitudeValue ?long .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?bronzeCap, ?steelCap .
  ?bronzeCap a sdk:BronzeProcessingCapability ;
             rdfs:label "Bronze" .
  ?steelCap a sdk:SteelProcessingCapability ;
            rdfs:label "Steel" .
  FILTER (?bronzeCap != ?steelCap)
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

ASK WHERE {
  ?m a iof-core:Manufacturer .
  FILTER NOT EXISTS { ?m sdk:hasCertificate ?cert . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

ASK {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?text .
  FILTER(CONTAINS(LCASE(STR(?name)), "coating"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?org ?label ?employees
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?label ;
       sdk:hasNumberOfEmployees ?emp .
  BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?employees)
  FILTER(?employees > 500)
}
ORDER BY DESC(?employees)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER regex(?name, "^A")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?naics ?text
WHERE {
  ?naics sdk:hasNAICSTextValue ?text .
  FILTER(CONTAINS(LCASE(STR(?text)), "pipe"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue "85027.0"^^xsd:string .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?org ?orgLabel ?state ?stateName
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  OPTIONAL { ?org rdfs:label ?orgLabel . }
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateName .
  FILTER regex(str(?stateName), "^New ")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                rdfs:label ?manufacturerLabel .
  ?industry a sdk:UtilitiesIndustry .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?name
WHERE {
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?name .
  FILTER(CONTAINS(LCASE(STR(?name)), "pipe"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER(STRLEN(STR(?name)) > 8)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?employees
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasNumberOfEmployees ?empLit ;
                rdfs:label ?label .
  BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?employees)
}
ORDER BY DESC(?employees)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?man ?manLabel ?emp
WHERE {
  {
    SELECT ?man ?manLabel (xsd:integer(REPLACE(STR(?empLit), "[^0-9-]", "")) AS ?emp)
    WHERE {
      ?man a iof-core:Manufacturer ;
           rdfs:label ?manLabel ;
           sdk:hasNumberOfEmployees ?empLit ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      FILTER(CONTAINS(LCASE(?stateLabel), "ohio"))
    }
  }
  {
    SELECT (MIN(xsd:integer(REPLACE(STR(?empLit2), "[^0-9-]", ""))) AS ?minEmp)
    WHERE {
      ?man2 a iof-core:Manufacturer ;
            sdk:hasNumberOfEmployees ?empLit2 ;
            sdk:organizationLocatedIn ?site2 .
      ?site2 sdk:locatedInCity ?city2 .
      ?city2 sdk:locatedInState ?state2 .
      ?state2 rdfs:label ?stateLabel2 .
      FILTER(CONTAINS(LCASE(?stateLabel2), "ohio"))
    }
  }
  FILTER(?emp = ?minEmp)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?org) AS ?numManufacturers)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?supplierCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?supplierCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificate ?certificateLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?certificate .
  OPTIONAL { ?certificate rdfs:label ?certificateLabel . }
}
GROUP BY ?certificate ?certificateLabel
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?productLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct .
  OPTIONAL { ?product rdfs:label ?productLabel . }
}
GROUP BY ?product ?productLabel
ORDER BY DESC(?manufacturerCount) ?product
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?pair) AS ?numDistinctProcessMaterialCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasProcessCapability ?process ;
                sdk:hasMaterialCapability ?material .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  BIND(CONCAT(STR(?process), "|", STR(?material)) AS ?pair)
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?numDistinctProcessMaterialCapabilities)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naics ?naicsCode ?naicsText (COUNT(DISTINCT ?org) AS ?manufacturerCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasPrimaryNAICSClassifier ?naics .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCode . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsText . }
}
GROUP BY ?naics ?naicsCode ?naicsText
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer ?naicsText
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    ?naics sdk:hasNAICSTextValue ?naicsText .
  }
}
ORDER BY ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer ?zip
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn/sdk:hasZIPcode/sdk:hasIntegerValue ?zip .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasProcessCapability ?cap .
  ?cap rdfs:label ?capLabel .
  FILTER (?capLabel IN ("Machining", "Coating"))
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerName (GROUP_CONCAT(DISTINCT ?capabilityName; separator=", ") AS ?capabilityNames)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerName . }
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?capability .
    ?capability rdfs:label ?capabilityName .
  }
}
GROUP BY ?manufacturer ?manufacturerName
ORDER BY ?manufacturerName

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?cityLabel ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
    }
    OPTIONAL {
      ?site (sdk:locatedInState | (sdk:locatedInCity/sdk:locatedInState)) ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel . }
    }
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                rdfs:label ?manufacturerLabel .
  VALUES ?industryType { sdk:RenewableEnergyIndustry sdk:UtilitiesIndustry }
  ?industry a ?industryType .
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?kind ?itemName WHERE {
  {
    ?m a iof-core:Manufacturer ;
       sdk:manufactures ?item .
    OPTIONAL { ?m rdfs:label ?manLabel . }
    OPTIONAL { ?item rdfs:label ?itemLabel . }
    BIND(COALESCE(?manLabel, STR(?m)) AS ?manufacturer)
    BIND(COALESCE(?itemLabel, STR(?item)) AS ?itemName)
    BIND("Product" AS ?kind)
  }
  UNION
  {
    ?m a iof-core:Manufacturer ;
       sdk:hasCertificate ?item .
    OPTIONAL { ?m rdfs:label ?manLabel2 . }
    OPTIONAL { ?item rdfs:label ?itemLabel2 . }
    BIND(COALESCE(?manLabel2, STR(?m)) AS ?manufacturer)
    BIND(COALESCE(?itemLabel2, STR(?item)) AS ?itemName)
    BIND("Certificate" AS ?kind)
  }
}
ORDER BY ?manufacturer ?kind ?itemName

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coords .
      OPTIONAL { ?coords sdk:hasLatitudeValue ?latitude . }
      OPTIONAL { ?coords sdk:hasLongitudeValue ?longitude . }
    }
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?text
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?descText .
  }
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  BIND(COALESCE(?descText, ?name, "") AS ?text)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerName ?capability ?capabilityName
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerName .
  {
    ?manufacturer sdk:hasProcessCapability ?capability .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?capability .
  }
  ?capability rdfs:label ?capabilityName .
}
ORDER BY ?manufacturerName ?capabilityName

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?city ?cityLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(?cityLabel), LCASE("Rochester")))
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state (SAMPLE(?lbl) AS ?stateLabel) (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?state rdfs:label ?lbl }
}
GROUP BY ?state
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?org) AS ?manufacturerCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city a sdk:City .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY ?cityLabel ?city

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?m ?label ?lat
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:organizationLocatedIn ?site .
  OPTIONAL { ?m rdfs:label ?label . }
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat .
  FILTER(xsd:float(?lat) > "40.0"^^xsd:float)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?label }
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLongitudeValue ?longitude .
  FILTER(xsd:double(?longitude) < 90.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?label }
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?lon .
  FILTER(?lat = "33.364638"^^xsd:float && ?lon = "-111.931604"^^xsd:float)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?cityName ?zipCode
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city ;
        sdk:hasZIPcode ?zip .
  ?city rdfs:label ?cityName .
  ?zip sdk:hasIntegerValue ?zipCode .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER (regex(?stateLabel, "^New "))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?employees
WHERE {
  {
    SELECT ?state ?manufacturer ?employees ?stateLabel ?manufacturerLabel
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:hasNumberOfEmployees ?empLit ;
                    sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel . }
      OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
      BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?employees)
    }
  }
  {
    SELECT ?state ?manufacturer ((1 + COUNT(DISTINCT ?m2)) AS ?rank)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:hasNumberOfEmployees ?empLit ;
                    sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?emp)

      ?m2 a iof-core:Manufacturer ;
          sdk:hasNumberOfEmployees ?empLit2 ;
          sdk:organizationLocatedIn ?site2 .
      ?site2 sdk:locatedInCity ?city2 .
      ?city2 sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?empLit2), ",", "")) AS ?emp2)

      FILTER(?emp2 > ?emp || (?emp2 = ?emp && STR(?m2) < STR(?manufacturer)))
    }
    GROUP BY ?state ?manufacturer
  }
  FILTER(?rank <= 3)
}
ORDER BY ?stateLabel ?rank DESC(?employees) ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?employeeBucket (COUNT(DISTINCT ?org) AS ?companyCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?empLit .
  BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?emp)
  BIND(
    IF(?emp <= 50, "Small",
      IF(?emp >= 51 && ?emp <= 250, "Medium",
        IF(?emp > 250, "Large", "Other")
      )
    ) AS ?employeeBucket
  )
  FILTER(?employeeBucket IN ("Small","Medium","Large"))
}
GROUP BY ?employeeBucket
ORDER BY ?employeeBucket

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?manufacturerLabel ?employeeCount ?industryAvg
WHERE {
  {
    SELECT ?ind (AVG(?emp2) AS ?industryAvg)
    WHERE {
      ?m2 a iof-core:Manufacturer ;
          sdk:suppliesToIndustry ?ind ;
          sdk:hasNumberOfEmployees ?empLit2 .
      BIND(xsd:decimal(REPLACE(STR(?empLit2), ",", "")) AS ?emp2)
    }
    GROUP BY ?ind
  }
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?ind ;
                sdk:hasNumberOfEmployees ?empLit .
  BIND(?ind AS ?industry)
  BIND(xsd:decimal(REPLACE(STR(?empLit), ",", "")) AS ?employeeCount)
  FILTER(?employeeCount > ?industryAvg)
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
  OPTIONAL { ?industry rdfs:label ?industryLabel }
}
ORDER BY ?industry ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?hasISO9001
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  BIND(EXISTS {
    ?manufacturer sdk:hasCertificate ?cert .
    ?cert a sdk:ISO9001 .
  } AS ?hasISO9001)
}
ORDER BY ?manufacturerLabel ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?category (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  VALUES (?category ?class ?keyword) {
    ("Machining" sdk:MachiningCapability "machining")
    ("Coating" sdk:CoatingCapability "coating")
    ("Heat Treating" UNDEF "heat treating")
  }
  OPTIONAL {
    ?m a iof-core:Manufacturer ;
       sdk:hasProcessCapability ?cap .
    OPTIONAL {
      ?cap a ?capClass .
      ?capClass rdfs:subClassOf* ?class .
    }
    OPTIONAL {
      ?cap rdfs:label ?capLabel .
      FILTER(CONTAINS(LCASE(STR(?capLabel)), ?keyword))
      BIND(true AS ?labelHit)
    }
    FILTER(BOUND(?capClass) || BOUND(?labelHit))
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel (AVG(?empNum) AS ?avgEmployees)
WHERE {
  {
    SELECT DISTINCT ?m ?state ?stateLabel ?empNum
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:manufactures ?prod ;
         sdk:hasNumberOfEmployees ?emp ;
         sdk:organizationLocatedIn ?site .
      ?prod rdfs:label ?prodLabel .
      FILTER(CONTAINS(STR(?prodLabel), "Pipe"))
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel }
      BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?empNum)
    }
  }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?manufacturer ?label ?certCount
WHERE {
  {
    SELECT ?manufacturer (COUNT(?cert) AS ?certCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
    }
    GROUP BY ?manufacturer
  }
  {
    SELECT (AVG(?cnt) AS ?avgCerts)
    WHERE {
      SELECT ?m (COUNT(?c) AS ?cnt)
      WHERE {
        ?m a iof-core:Manufacturer .
        OPTIONAL { ?m sdk:hasCertificate ?c . }
      }
      GROUP BY ?m
    }
  }
  FILTER(?certCount > ?avgCerts)
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
ORDER BY DESC(?certCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naics ?naicsText ?state ?stateLabel ?count
WHERE {
  {
    SELECT ?naics ?state (COUNT(?org) AS ?count)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasPrimaryNAICSClassifier ?naics ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
    }
    GROUP BY ?naics ?state
  }
  {
    SELECT ?naics ?state (COUNT(?stateHigher) AS ?numHigher)
    WHERE {
      {
        SELECT ?naics ?state (COUNT(?org) AS ?count)
        WHERE {
          ?org a iof-core:Manufacturer ;
               sdk:hasPrimaryNAICSClassifier ?naics ;
               sdk:organizationLocatedIn ?site .
          ?site sdk:locatedInCity ?city .
          ?city sdk:locatedInState ?state .
        }
        GROUP BY ?naics ?state
      }
      OPTIONAL {
        {
          SELECT ?naics ?stateHigher (COUNT(?orgH) AS ?countHigher)
          WHERE {
            ?orgH a iof-core:Manufacturer ;
                  sdk:hasPrimaryNAICSClassifier ?naics ;
                  sdk:organizationLocatedIn ?siteH .
            ?siteH sdk:locatedInCity ?cityH .
            ?cityH sdk:locatedInState ?stateHigher .
          }
          GROUP BY ?naics ?stateHigher
        }
        FILTER(?countHigher > ?count)
      }
    }
    GROUP BY ?naics ?state
  }
  FILTER(?numHigher < 5)
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsText . }
}
ORDER BY ?naics DESC(?count) ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?cityState
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
      OPTIONAL {
        ?city sdk:locatedInState ?state .
        OPTIONAL { ?state rdfs:label ?stateLabel . }
      }
    }
  }
  BIND(COALESCE(?cityLabel, "Unknown") AS ?cityName)
  BIND(COALESCE(?stateLabel, "Unknown") AS ?stateName)
  BIND(CONCAT(?cityName, ", ", ?stateName) AS ?cityState)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasProcessCapability ?capability .
  ?capability a ?capClass .
  ?capClass rdfs:subClassOf* sdk:MachiningCapability .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?m) AS ?count)
WHERE {
  ?m a iof-core:Manufacturer ;
