PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasNumberOfEmployees ?empLiteral ;
                sdk:hasProcessCapability ?cap ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label "Arizona" .

  ?cap a ?capType .
  ?capType rdfs:subClassOf* sdk:AdditiveManufacturingCapability .

  BIND(xsd:integer(REPLACE(STR(?empLiteral), ",", "")) AS ?emp)
  FILTER(?emp > 50)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert ;
                sdk:suppliesToIndustry ?aeroInd, ?autoInd .
  ?cert a sdk:ISO9001 .
  ?aeroInd rdfs:label ?aeroLabel .
  ?autoInd rdfs:label ?autoLabel .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  FILTER(CONTAINS(LCASE(STR(?aeroLabel)), "aerospace"))
  FILTER(CONTAINS(LCASE(STR(?autoLabel)), "automotive"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasProcessCapability ?cap ;
                sdk:hasNumberOfEmployees ?empRaw .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  ?industry a sdk:RenewableEnergyIndustry .
  ?cap a ?capClass .
  ?capClass rdfs:subClassOf* sdk:CoatingCapability .
  BIND(xsd:integer(REPLACE(STR(?empRaw), ",", "")) AS ?emp)
  FILTER(?emp > 200)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?productCount
WHERE {
  {
    SELECT ?state ?manufacturer (COUNT(DISTINCT ?product) AS ?productCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:organizationLocatedIn ?site ;
                    sdk:manufactures ?product .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      FILTER EXISTS { ?manufacturer sdk:hasCertificate ?cert . }
    }
    GROUP BY ?state ?manufacturer
  }
  {
    SELECT ?state (MAX(?pc) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?manufacturer (COUNT(DISTINCT ?product) AS ?pc)
        WHERE {
          ?manufacturer a iof-core:Manufacturer ;
                        sdk:organizationLocatedIn ?site2 ;
                        sdk:manufactures ?product .
          ?site2 sdk:locatedInCity ?city2 .
          ?city2 sdk:locatedInState ?state .
          FILTER EXISTS { ?manufacturer sdk:hasCertificate ?c . }
        }
        GROUP BY ?state ?manufacturer
      }
    }
    GROUP BY ?state
  }
  FILTER (?productCount = ?maxCount)
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY ?state ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?matCap ;
                sdk:organizationLocatedIn ?site ;
                rdfs:label ?manufacturerLabel .
  ?matCap a sdk:CeramicProcessingCapability .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateLabel .
  FILTER(STRSTARTS(LCASE(STR(?stateLabel)), "new"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?supplier) AS ?supplierCount)
WHERE {
  ?supplier a iof-core:Manufacturer ;
            sdk:suppliesToIndustry ?industry ;
            sdk:manufactures ?product .
  ?product rdfs:label ?prodLabel .
  FILTER(regex(str(?prodLabel), "pipe", "i"))
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
HAVING (COUNT(DISTINCT ?supplier) > 100)
ORDER BY DESC(?supplierCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasProcessCapability ?capM , ?capS .
  ?industry rdfs:label "Automotive" .
  ?capM a sdk:MachiningCapability .
  ?capS a sdk:SurfaceFinishingCapability .
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?matCap ;
                sdk:organizationLocatedIn ?manuSite .
  ?matCap a sdk:GraphiteProcessingCapability .
  ?manuSite sdk:locatedInCity ?manuCity .
  ?manuCity sdk:locatedInState ?state .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }

  ?supplier sdk:organizationLocatedIn ?supSite ;
            sdk:suppliesToIndustry ?industry .
  ?industry a sdk:RenewableEnergyIndustry .
  ?supSite sdk:locatedInCity ?supCity .
  ?supCity sdk:locatedInState ?state .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?city ?cityLabel (AVG(?emp) AS ?avgEmployeeCount)
WHERE {
  {
    SELECT DISTINCT ?city ?cityLabel ?org (xsd:integer(REPLACE(STR(?rawEmp), ",", "")) AS ?emp)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasProcessCapability ?cap ;
           sdk:organizationLocatedIn ?site ;
           sdk:hasNumberOfEmployees ?rawEmp .
      ?cap a ?capType .
      VALUES ?capType {
        sdk:HeatTreatingCapability
        sdk:StressRelievingCapability
        sdk:ThroughHardeningCapability
        sdk:AustemperingCapability
        sdk:TemperingCapability
        sdk:FullAnnealingCapability
        sdk:SurfaceHardeningCapability
        sdk:AnnealingCapability
        sdk:HardeningCapability
        sdk:ColdTreatmentCapability
      }
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
    }
  }
}
GROUP BY ?city ?cityLabel
ORDER BY ?cityLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?lat
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?indAgri ;
                sdk:suppliesToIndustry ?indConstr ;
                sdk:organizationLocatedIn ?site .
  ?indAgri rdfs:label ?agriLabel .
  ?indConstr rdfs:label ?constrLabel .
  FILTER(LCASE(STR(?agriLabel)) = "agriculture")
  FILTER(LCASE(STR(?constrLabel)) = "construction")
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat .
  FILTER(xsd:float(?lat) > 40.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?industry ?industryLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?company rdfs:label ?companyLabel . }
  ?industry rdfs:label ?industryLabel .
  FILTER(CONTAINS(LCASE(STR(?industryLabel)), "automotive"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           sdk:hasMaterialCapability ?cap .
  ?cap a sdk:CeramicProcessingCapability .
  OPTIONAL { ?company rdfs:label ?companyLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?manufacturerLabel ?employees
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasNumberOfEmployees ?empLit .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?employees)
}
ORDER BY DESC(?employees)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           sdk:hasProcessCapability ?cap .
  ?cap a ?capClass .
  VALUES ?capClass {
    sdk:AdditiveManufacturingCapability
    sdk:PowderDepositionCapability
    sdk:SolidDepositionCapability
    sdk:FusedDepositionModelingCapability
    sdk:PolymerDepositionCapability
    sdk:DropOnDemandCapability
    sdk:SelectiveLaserMeltingCapability
    sdk:LaminatedObjectManufacturingCapability
  }
  OPTIONAL { ?company rdfs:label ?companyLabel }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?sector ?sectorLabel ?supplierCount
WHERE {
  {
    SELECT ?sector (COUNT(DISTINCT ?org) AS ?supplierCount)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:suppliesToIndustry ?sector .
    }
    GROUP BY ?sector
  }
  OPTIONAL { ?sector rdfs:label ?sectorLabel }
  {
    SELECT (MAX(?c) AS ?maxCount)
    WHERE {
      SELECT ?sector2 (COUNT(DISTINCT ?org2) AS ?c)
      WHERE {
        ?org2 a iof-core:Manufacturer ;
              sdk:suppliesToIndustry ?sector2 .
      }
      GROUP BY ?sector2
    }
  }
  FILTER (?supplierCount = ?maxCount)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?employees
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasNumberOfEmployees ?emp ;
                rdfs:label ?label .
  BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?employees)
  FILTER(?employees >= 100)
}
ORDER BY DESC(?employees)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?descText ?length
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?descText .
  BIND(STRLEN(STR(?descText)) AS ?length)
  FILTER(?length > 20)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?naics ?code ?text
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasPrimaryNAICSClassifier ?naics ;
                rdfs:label ?manufacturerLabel .
  ?naics sdk:hasNAICSCodeValue ?code ;
         sdk:hasNAICSTextValue ?text .
  FILTER(STRSTARTS(STR(?code), "332996"))
  FILTER(CONTAINS(LCASE(STR(?text)), "pipe"))
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?industry) = 2)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasProcessCapability ?proc ;
                sdk:hasMaterialCapability ?mat .
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?cap) = 4)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:suppliesToIndustry ?ind .

  FILTER EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?reInd .
    ?reInd a sdk:RenewableEnergyIndustry .
  }

  FILTER EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?utInd .
    ?utInd a sdk:UtilitiesIndustry .
  }

  FILTER NOT EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?otherInd .
    FILTER NOT EXISTS { ?otherInd a sdk:RenewableEnergyIndustry }
    FILTER NOT EXISTS { ?otherInd a sdk:UtilitiesIndustry }
  }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?ind) = 2)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org ?orgLabel
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:suppliesToIndustry ?ind ;
       sdk:suppliesToIndustry ?renInd ;
       sdk:suppliesToIndustry ?utilInd .
  ?renInd a sdk:RenewableEnergyIndustry .
  ?utilInd a sdk:UtilitiesIndustry .
  OPTIONAL { ?org rdfs:label ?orgLabel. }
}
GROUP BY ?org ?orgLabel
HAVING (COUNT(DISTINCT ?ind) = 2)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?c1, ?c2 .
  ?c1 a sdk:ISO9001 .
  ?c2 a sdk:ISO14001 .
  OPTIONAL { ?manufacturer rdfs:label ?name }
}
ORDER BY ?name ?manufacturer

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org ?orgLabel ?count
WHERE {
  {
    SELECT ?org (COUNT(DISTINCT ?prod) AS ?count)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:manufactures ?prod .
      ?prod a iof-core:MaterialProduct .
    }
    GROUP BY ?org
  }
  {
    SELECT (MAX(?c) AS ?maxCount)
    WHERE {
      SELECT ?org (COUNT(DISTINCT ?prod) AS ?c)
      WHERE {
        ?org a iof-core:Manufacturer ;
             sdk:manufactures ?prod .
        ?prod a iof-core:MaterialProduct .
      }
      GROUP BY ?org
    }
  }
  FILTER (?count = ?maxCount)
  OPTIONAL { ?org rdfs:label ?orgLabel }
}
ORDER BY ?org

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?industryType ?supplierCount
WHERE {
  {
    SELECT ?industryType (COUNT(DISTINCT ?m) AS ?supplierCount)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?ind .
      ?ind a ?industryType .
    }
    GROUP BY ?industryType
  }
  {
    SELECT (MAX(?cnt) AS ?maxCount)
    WHERE {
      {
        SELECT ?industryType (COUNT(DISTINCT ?m) AS ?cnt)
        WHERE {
          ?m a iof-core:Manufacturer ;
             sdk:suppliesToIndustry ?ind .
          ?ind a ?industryType .
        }
        GROUP BY ?industryType
      }
    }
  }
  FILTER(?supplierCount = ?maxCount)
}
ORDER BY ?industryType

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?org ?orgLabel ?headcount
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?orgLabel ;
       sdk:hasNumberOfEmployees ?empLit ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateLabel .
  BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?headcount)

  {
    SELECT ?state (MAX(?emp) AS ?maxEmp)
    WHERE {
      ?org2 a iof-core:Manufacturer ;
             sdk:hasNumberOfEmployees ?empLit2 ;
             sdk:organizationLocatedIn ?site2 .
      ?site2 sdk:locatedInCity ?city2 .
      ?city2 sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?empLit2), ",", "")) AS ?emp)
    }
    GROUP BY ?state
  }

  FILTER(?headcount = ?maxEmp)
}
ORDER BY ?stateLabel ?orgLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?cityState
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
      OPTIONAL {
        ?city sdk:locatedInState ?state .
        OPTIONAL { ?state rdfs:label ?stateLabel . }
      }
    }
  }
  BIND(STR(COALESCE(?cityLabel, "Unknown")) AS ?cityStr)
  BIND(STR(COALESCE(?stateLabel, "Unknown")) AS ?stateStr)
  BIND(CONCAT(?cityStr, ", ", ?stateStr) AS ?cityState)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?coordinates
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coord .
      OPTIONAL { ?coord sdk:hasLatitudeValue ?lat . }
      OPTIONAL { ?coord sdk:hasLongitudeValue ?long . }
    }
  }
  BIND(IF(BOUND(?lat) && BOUND(?long),
           CONCAT(STR(?lat), ",", STR(?long)),
           "no-coords") AS ?coordinates)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer (COALESCE(?zipVal, ?addrText, ?name) AS ?preferredValue)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasZIPcode ?zip .
      ?zip sdk:hasIntegerValue ?zipVal .
    }
    OPTIONAL {
      ?site sdk:hasPostalAddress ?addr .
      ?addr iof-scro:hasTextValue ?addrText .
    }
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?capabilityLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?capability .
  ?capability rdfs:label ?capabilityLabel .
}
ORDER BY ?manufacturerLabel ?capabilityLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  {
    ?manufacturer sdk:hasProcessCapability ?procCap .
    ?procCap rdfs:label ?procLabel .
    FILTER regex(str(?procLabel), "ing$", "i")
  }
  UNION
  {
    ?manufacturer sdk:hasMaterialCapability ?matCap .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerName ?site ?city ?cityName ?state ?stateName
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerName ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityName ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateName .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:locatedInCity ?city .
    ?city sdk:locatedInState ?state .
  }
  UNION
  {
    ?manufacturer sdk:locatedInState ?state .
  }
  ?state a sdk:State .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerName
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerName ;
                sdk:hasProcessCapability ?cap .
  ?cap rdfs:label ?capLabel .
}
GROUP BY ?manufacturer ?manufacturerName
HAVING (COUNT(?cap) > 0 && SUM(IF(STRENDS(LCASE(STR(?capLabel)), "ing"), 0, 1)) = 0)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel .

  FILTER EXISTS {
    ?manufacturer sdk:hasMaterialCapability ?capAllowed .
    ?capAllowed a ?typeAllowed .
    FILTER(?typeAllowed IN (
      sdk:UrethaneProcessingCapability,
      sdk:StainlessSteelProcessingCapability,
      sdk:BronzeProcessingCapability
    ))
  }

  FILTER NOT EXISTS {
    ?manufacturer sdk:hasMaterialCapability ?capOther .
    ?capOther a ?typeOther .
    FILTER(?typeOther NOT IN (
      sdk:UrethaneProcessingCapability,
      sdk:StainlessSteelProcessingCapability,
      sdk:BronzeProcessingCapability
    ))
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?site
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site a sdk:GeospatialLocation .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL { ?site sdk:hasSpatialCoordinates ?coord . }
  OPTIONAL { ?coord sdk:hasLatitudeValue ?lat . }
  OPTIONAL { ?coord sdk:hasLongitudeValue ?lon . }
  FILTER(!BOUND(?lat) || !BOUND(?lon))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert .
  FILTER NOT EXISTS { ?manufacturer sdk:manufactures ?product }
  OPTIONAL { ?manufacturer rdfs:label ?label }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    OPTIONAL { ?desc iof-scro:hasTextValue ?txt . }
  }
  FILTER ( !BOUND(?desc) || !BOUND(?txt) || REGEX(STR(?txt), "^\\s*$") )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  FILTER NOT EXISTS { ?manufacturer sdk:suppliesToIndustry ?industry . }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?certCount
WHERE {
  {
    SELECT ?manufacturer (COUNT(DISTINCT ?cert) AS ?certCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
    }
    GROUP BY ?manufacturer
  }
  {
    SELECT (AVG(?cnt) AS ?avgCerts)
    WHERE {
      SELECT ?m (COUNT(DISTINCT ?c) AS ?cnt)
      WHERE {
        ?m a iof-core:Manufacturer .
        OPTIONAL { ?m sdk:hasCertificate ?c . }
      }
      GROUP BY ?m
    }
  }
  FILTER (?certCount > ?avgCerts)
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY DESC(?certCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?manufacturerLabel ?employeeCount ?avgEmp
WHERE {
  {
    SELECT ?industry (AVG(xsd:decimal(?emp)) AS ?avgEmp)
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry ;
         sdk:hasNumberOfEmployees ?emp .
    }
    GROUP BY ?industry
  }
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasNumberOfEmployees ?emp2 ;
                rdfs:label ?manufacturerLabel .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
  BIND(xsd:decimal(?emp2) AS ?employeeCount)
  FILTER(?employeeCount > ?avgEmp)
}
ORDER BY ?industryLabel ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel
       (COUNT(DISTINCT ?pCap) AS ?totalProcessCapabilities)
       (COUNT(DISTINCT ?mCap) AS ?totalMaterialCapabilities)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  OPTIONAL { ?org sdk:hasProcessCapability ?pCap . }
  OPTIONAL { ?org sdk:hasMaterialCapability ?mCap . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  ?naicsCode
  ?naicsText
  (COUNT(DISTINCT ?org) AS ?manufacturerCount)
  (COUNT(DISTINCT ?prod) AS ?totalProductCount)
  (AVG(DISTINCT ?empClean) AS ?avgEmployeeCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasPrimaryNAICSClassifier ?naicsInst .
  ?naicsInst sdk:hasNAICSCodeValue ?naicsCode .
  OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsText . }
  OPTIONAL { ?org sdk:manufactures ?prod . }
  OPTIONAL {
    ?org sdk:hasNumberOfEmployees ?empLit .
    BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?empClean)
  }
}
GROUP BY ?naicsCode ?naicsText
ORDER BY ?naicsCode

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name
WHERE {
  ?org a iof-core:Manufacturer .
  {
    ?org rdfs:label ?name .
    FILTER(langMatches(lang(?name), "en"))
  }
  UNION
  {
    ?org rdfs:label ?name .
    FILTER(lang(?name) = "")
    FILTER NOT EXISTS {
      ?org rdfs:label ?enName .
      FILTER(langMatches(lang(?enName), "en"))
    }
  }
}
ORDER BY ?name

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT DISTINCT ?manufacturer ?name ?description
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?description .
  }
  FILTER(
    (BOUND(?name) && CONTAINS(LCASE(STR(?name)), "company")) ||
    (BOUND(?description) && CONTAINS(LCASE(STR(?description)), "company"))
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?product ?productLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                rdfs:label ?manufacturerLabel .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
  FILTER(?productLabel = "Tube Bending" || ?productLabel = "Punching")
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?city ?cityLabel (AVG(?emp) AS ?avgEmployeeCount)
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?empLit ;
       sdk:organizationLocatedIn ?site .
  BIND(xsd:integer(REPLACE(STR(?empLit), ",", "")) AS ?emp)
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }

  {
    SELECT ?org (COUNT(DISTINCT ?cap) AS ?capCount)
    WHERE {
      ?org a iof-core:Manufacturer .
      { ?org sdk:hasProcessCapability ?cap . }
      UNION
      { ?org sdk:hasMaterialCapability ?cap . }
    }
    GROUP BY ?org
  }
  FILTER(?capCount >= 4)
}
GROUP BY ?city ?cityLabel
ORDER BY ?cityLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?zipString ?lat
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords ;
        sdk:hasZIPcode ?zipRes ;
        sdk:locatedInCity ?city .
  ?coords sdk:hasLatitudeValue ?lat .
  ?zipRes sdk:hasIntegerValue ?zip .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label "Arizona" .
  BIND(STR(?zip) AS ?zipString)
  FILTER(?lat > "33.4"^^xsd:float)
  FILTER(?zipString != "85001")
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer sdk:manufactures ?prod . }
  OPTIONAL { ?manufacturer sdk:hasProcessCapability ?pc . }
  OPTIONAL { ?manufacturer sdk:hasMaterialCapability ?mc . }
}
GROUP BY ?manufacturer
HAVING (
  (COUNT(DISTINCT ?prod) = 2)
  ||
  ((COUNT(DISTINCT ?pc) = 2) && (COUNT(DISTINCT ?mc) = 2))
)
